from fastapi import FastAPI
from pydantic import BaseModel
import joblib

app = FastAPI()
model = joblib.load('model.pkl')

class InputData(BaseModel):
    features: list[float]

@app.post('/predict')
def predict(data: InputData):
    pred = model.predict([data.features])
    return {'prediction': pred.tolist()}
